mapper.update:
UPDATE sys_ehr_sync_run
SET status = 'RUNNING', started_at = #{startedAt}
WHERE id = #{runId} AND status = 'PENDING'

mapper.select:
SELECT id, run_id, severity, issue_code, employee_no,
       failure_stage, detail_digest, created_at
FROM sys_ehr_sync_issue
WHERE run_id = #{runId}
  AND id > #{afterId}
ORDER BY id
LIMIT #{limit}

